select x.monster_id, x.region_id, x.monster_name, x.monster_type, x.min_level, x.max_level, x.hp, x.attack_power, x.spawn_weight, x.description, x.drops, x.difficulty_rank, x.mechanic_key, x.mechanic_description, x.role, x.kind from jsonb_to_recordset($J$[{"monster_id":"mk_field_1","region_id":"blank_field","monster_name":"떠도는 먹귀","monster_type":"원령","min_level":41,"max_level":44,"hp":644,"attack_power":53,"spawn_weight":14,"description":"거둬진 이름의 미련이 먹물 꼴로 굳었다. 지나는 이의 소매를 붙들고 「기억해 줘」라고 속삭인다.","drops":{"drifting_name_thread":1,"meokgwi_lump":1},"difficulty_rank":2,"mechanic_key":"spectral","mechanic_description":"몸이 반쯤 비친다. 물리 공격이 덜 듣고 술법이 잘 듣는다.","role":"common","kind":"ghost"},{"monster_id":"mk_field_2","region_id":"blank_field","monster_name":"빈칸 까마귀 떼","monster_type":"비행 요괴","min_level":41,"max_level":44,"hp":644,"attack_power":53,"spawn_weight":14,"description":"지운 문패의 글자를 쪼아 먹는 까마귀 떼. 한 마리가 울면 하늘이 새카매진다.","drops":{"blank_hanji":1,"meokgwi_lump":1},"difficulty_rank":2,"mechanic_key":"aerial","mechanic_description":"하늘에서 내리꽂는다. 원거리 사격이 잘 듣는다.","role":"common","kind":"bird"},{"monster_id":"mk_field_3","region_id":"blank_field","monster_name":"문패 뜯는 손","monster_type":"매복 요괴","min_level":43,"max_level":46,"hp":6150,"attack_power":308,"spawn_weight":15,"description":"억새 그늘에 숨어 있다가 문패를 뜯듯 사람의 이름을 잡아챈다.","drops":{"erased_plate":2,"drifting_name_thread":2,"meokgwi_lump":1},"difficulty_rank":5,"mechanic_key":"ambush","mechanic_description":"숨어 있다 먼저 친다. 낌새를 살피고 방어를 섞어라.","role":"main","kind":"shadow"},{"monster_id":"mk_field_4","region_id":"blank_field","monster_name":"먹물 두꺼비","monster_type":"독충","min_level":43,"max_level":46,"hp":6150,"attack_power":308,"spawn_weight":15,"description":"고랑에 고인 먹물을 마시고 부풀어 오른 두꺼비. 내뿜는 숨에 독이 섞였다.","drops":{"mukchang_ink":2,"venom_gland":1,"drifting_name_thread":1},"difficulty_rank":5,"mechanic_key":"toxic","mechanic_description":"독을 뿜는다. 해독할 약초와 회복품을 챙겨라.","role":"main","kind":"venom"},{"monster_id":"mk_field_5","region_id":"blank_field","monster_name":"이름 걸린 허수아비","monster_type":"지역 우두머리","min_level":41,"max_level":43,"hp":966,"attack_power":74,"spawn_weight":12,"description":"벌판 한가운데 선 거대한 허수아비. 몸에 지운 문패를 수백 장 매달았다.","drops":{"erased_plate":3,"drifting_name_thread":2,"spirit_core":1},"difficulty_rank":10,"mechanic_key":"boss","mechanic_description":"보스급 위협. 세 번째 행동마다 광역급 강공격을 하므로 방어 태세를 섞어라.","role":"guardian","kind":"giant"},{"monster_id":"mk_forest_1","region_id":"meokbi_forest","monster_name":"먹비 넋","monster_type":"수귀","min_level":42,"max_level":45,"hp":658,"attack_power":54,"spawn_weight":14,"description":"빗물에 섞여 내리는 넋. 발목을 감고 웅덩이로 끌어당긴다.","drops":{"meokbi_moss":1,"meokgwi_lump":1},"difficulty_rank":2,"mechanic_key":"tide","mechanic_description":"물살로 끌어당겨 발을 묶는다. 거리를 두고 싸우거나 묶이기 전에 끊어라.","role":"common","kind":"water"},{"monster_id":"mk_forest_2","region_id":"meokbi_forest","monster_name":"흑단 덩굴귀","monster_type":"목령","min_level":42,"max_level":45,"hp":658,"attack_power":54,"spawn_weight":14,"description":"흑단 가지에 붙어 사는 덩굴 요괴. 가시에 먹물 독이 배었다.","drops":{"meokbi_ebony":1,"meokgwi_lump":1},"difficulty_rank":2,"mechanic_key":"toxic","mechanic_description":"독을 뿜는다. 해독할 약초와 회복품을 챙겨라.","role":"common","kind":"wood"},{"monster_id":"mk_forest_3","region_id":"meokbi_forest","monster_name":"먹비 반딧불 떼","monster_type":"무리 요괴","min_level":44,"max_level":46,"hp":6300,"attack_power":315,"spawn_weight":15,"description":"남의 꿈을 한 조각씩 물고 나는 검은 반딧불. 떼로 몰려와 눈을 가린다.","drops":{"meokbi_moss":2,"drifting_name_thread":2,"meokgwi_lump":1},"difficulty_rank":5,"mechanic_key":"swarm","mechanic_description":"떼로 몰려든다. 세 번째 행동마다 강하게 반격한다.","role":"main","kind":"swarm"},{"monster_id":"mk_forest_4","region_id":"meokbi_forest","monster_name":"먹 먹은 목장승","monster_type":"갑각 요괴","min_level":44,"max_level":46,"hp":6300,"attack_power":315,"spawn_weight":15,"description":"먹비를 백 년 맞아 돌처럼 굳은 장승. 새긴 이름이 지워져 누구를 지키는지 모른다.","drops":{"meokbi_ebony":2,"monster_core":1,"drifting_name_thread":1},"difficulty_rank":5,"mechanic_key":"armored","mechanic_description":"껍질이 단단하다. 방어를 무시하는 공격이나 술법이 낫다.","role":"main","kind":"shell"},{"monster_id":"mk_forest_5","region_id":"meokbi_forest","monster_name":"꺾인 붓 고목","monster_type":"지역 우두머리","min_level":42,"max_level":44,"hp":987,"attack_power":76,"spawn_weight":12,"description":"붓대처럼 곧던 고목이 꺾인 자리에서 요괴가 되었다. 가지를 흔들 때마다 봉인 먹이 번진다.","drops":{"meokbi_ebony":3,"drifting_name_thread":2,"spirit_core":1},"difficulty_rank":10,"mechanic_key":"seal_breaker","mechanic_description":"봉인을 약하게 만든다. 부적과 봉인 재료를 챙겨라.","role":"guardian","kind":"breaker"},{"monster_id":"mk_tower_1","region_id":"myeongbu_tower","monster_name":"명부 갈피귀","monster_type":"결계 요괴","min_level":44,"max_level":45,"hp":686,"attack_power":56,"spawn_weight":14,"description":"죽간 사이에 끼어 사는 요괴. 갈피마다 금줄을 둘러 몸을 감싼다.","drops":{"register_slip":1,"meokgwi_lump":1},"difficulty_rank":2,"mechanic_key":"warded","mechanic_description":"결계를 두른다. 결계를 깨는 한 방을 모아 두어라.","role":"common","kind":"ward"},{"monster_id":"mk_tower_2","region_id":"myeongbu_tower","monster_name":"탑 꼭대기 번갯불","monster_type":"천상 요괴","min_level":44,"max_level":45,"hp":686,"attack_power":56,"spawn_weight":14,"description":"탑 꼭대기에 떨어진 번개가 흩어지지 않고 남았다. 창틀을 타고 내리꽂힌다.","drops":{"star_sand":1,"meokgwi_lump":1},"difficulty_rank":2,"mechanic_key":"aerial","mechanic_description":"하늘에서 내리꽂는다. 원거리 사격이 잘 듣는다.","role":"common","kind":"sky"},{"monster_id":"mk_tower_3","region_id":"myeongbu_tower","monster_name":"거울 명부","monster_type":"거울 요괴","min_level":45,"max_level":46,"hp":6600,"attack_power":330,"spawn_weight":15,"description":"이름 대신 얼굴을 비춰 적는 명부. 공격을 받으면 그 모습을 되비춘다.","drops":{"register_slip":2,"mirror_shard":2,"drifting_name_thread":1},"difficulty_rank":5,"mechanic_key":"reflect","mechanic_description":"공격의 일부를 되돌린다. 원거리 사격이나 봉인 제압을 써라.","role":"main","kind":"mirror"},{"monster_id":"mk_tower_4","region_id":"myeongbu_tower","monster_name":"이름 지우는 서리귀","monster_type":"원령","min_level":45,"max_level":46,"hp":6600,"attack_power":330,"spawn_weight":15,"description":"평생 명부의 이름을 지우던 서리의 넋. 지금도 붓을 들고 탑을 오르내린다.","drops":{"register_slip":2,"ghost_ash":3,"drifting_name_thread":1},"difficulty_rank":5,"mechanic_key":"spectral","mechanic_description":"몸이 반쯤 비친다. 물리 공격이 덜 듣고 술법이 잘 듣는다.","role":"main","kind":"ghost"},{"monster_id":"mk_tower_5","region_id":"myeongbu_tower","monster_name":"엉킨 먹귀 무리","monster_type":"지역 우두머리","min_level":44,"max_level":45,"hp":1029,"attack_power":79,"spawn_weight":12,"description":"탑 꼭대기에 모인 마지막 먹귀들이 서로 엉켜 한 덩어리가 되었다.","drops":{"register_slip":3,"drifting_name_thread":2,"spirit_core":1},"difficulty_rank":10,"mechanic_key":"swarm","mechanic_description":"떼로 몰려든다. 세 번째 행동마다 강하게 반격한다.","role":"guardian","kind":"swarm"},{"monster_id":"mk_court_1","region_id":"nine_court","monster_name":"칸 지키는 돌거북","monster_type":"갑각 요괴","min_level":45,"max_level":45,"hp":700,"attack_power":58,"spawn_weight":14,"description":"진의 칸마다 엎드린 돌거북. 등에 새긴 글자가 반쯤 지워졌다.","drops":{"erased_plate":1,"meokgwi_lump":1},"difficulty_rank":2,"mechanic_key":"armored","mechanic_description":"껍질이 단단하다. 방어를 무시하는 공격이나 술법이 낫다.","role":"common","kind":"shell"},{"monster_id":"mk_court_2","region_id":"nine_court","monster_name":"지워진 칸의 그림자","monster_type":"매복 요괴","min_level":45,"max_level":45,"hp":700,"attack_power":58,"spawn_weight":14,"description":"먹이 벗겨진 칸에서 일어서는 그림자. 밟는 순간 발목을 잡는다.","drops":{"register_slip":1,"meokgwi_lump":1},"difficulty_rank":2,"mechanic_key":"ambush","mechanic_description":"숨어 있다 먼저 친다. 낌새를 살피고 방어를 섞어라.","role":"common","kind":"shadow"},{"monster_id":"mk_court_3","region_id":"nine_court","monster_name":"우물가 먹귀","monster_type":"수귀","min_level":45,"max_level":46,"hp":6750,"attack_power":338,"spawn_weight":15,"description":"뜰 끝 우물에서 기어 나오는 먹귀. 물살처럼 몸을 펴 사람을 우물로 당긴다.","drops":{"mukchang_ink":2,"drowned_scale":1,"drifting_name_thread":1},"difficulty_rank":5,"mechanic_key":"tide","mechanic_description":"물살로 끌어당겨 발을 묶는다. 거리를 두고 싸우거나 묶이기 전에 끊어라.","role":"main","kind":"water"},{"monster_id":"mk_court_4","region_id":"nine_court","monster_name":"진 그리는 손","monster_type":"파봉 요괴","min_level":45,"max_level":46,"hp":6750,"attack_power":338,"spawn_weight":15,"description":"바닥의 진을 고쳐 그리려는 손 하나. 그릴 때마다 봉인이 비틀린다.","drops":{"register_slip":2,"ward_fragment":2,"drifting_name_thread":1},"difficulty_rank":5,"mechanic_key":"seal_breaker","mechanic_description":"봉인을 약하게 만든다. 부적과 봉인 재료를 챙겨라.","role":"main","kind":"breaker"},{"monster_id":"mk_court_5","region_id":"nine_court","monster_name":"아홉째 칸의 먹귀","monster_type":"지역 우두머리","min_level":45,"max_level":45,"hp":1050,"attack_power":80,"spawn_weight":12,"description":"아홉째 칸에 묶인 채 커다랗게 부푼 먹귀. 몸에서 이름들이 흘러내린다.","drops":{"register_slip":3,"drifting_name_thread":2,"spirit_core":1},"difficulty_rank":10,"mechanic_key":"boss","mechanic_description":"보스급 위협. 세 번째 행동마다 광역급 강공격을 하므로 방어 태세를 섞어라.","role":"guardian","kind":"giant"}]$J$::jsonb) as x(monster_id text, region_id text, monster_name text, monster_type text, min_level int, max_level int, hp int, attack_power int, spawn_weight int, description text, drops jsonb, difficulty_rank int, mechanic_key text, mechanic_description text, role text, kind text)
on conflict (monster_id) do update set monster_name = excluded.monster_name, description = excluded.description, drops = excluded.drops, min_level = excluded.min_level, max_level = excluded.max_level, hp = excluded.hp, attack_power = excluded.attack_power, mechanic_key = excluded.mechanic_key, kind = excluded.kind, role = excluded.role;
insert into public.world_expedition_grounds(ground_id, region_id, ground_name, description, depth, danger, min_level, unlock_progress)
select x.ground_id, x.region_id, x.ground_name, x.description, x.depth, x.danger, x.min_level, x.unlock_progress from jsonb_to_recordset($J$[{"ground_id":"blank_field_1","region_id":"blank_field","ground_name":"흰 억새 들머리","description":"억새가 먹 얼룩을 덮어 주는 바깥 들판.","depth":1,"danger":10,"min_level":41,"unlock_progress":0},{"ground_id":"blank_field_2","region_id":"blank_field","ground_name":"지운 문패 고랑","description":"뜯긴 문패가 고랑마다 쌓인 벌판 안쪽.","depth":2,"danger":10,"min_level":43,"unlock_progress":30},{"ground_id":"blank_field_3","region_id":"blank_field","ground_name":"부르다 만 고개","description":"누군가 이름을 부르다 멈춘 벌판 끝.","depth":3,"danger":10,"min_level":45,"unlock_progress":70},{"ground_id":"meokbi_forest_1","region_id":"meokbi_forest","ground_name":"비가림 숲길","description":"먹비가 덜 들이치는 바깥 숲길.","depth":1,"danger":10,"min_level":42,"unlock_progress":0},{"ground_id":"meokbi_forest_2","region_id":"meokbi_forest","ground_name":"흑단 고목 숲","description":"꿈이 비치는 웅덩이가 이어진 숲 안쪽.","depth":2,"danger":10,"min_level":44,"unlock_progress":30},{"ground_id":"meokbi_forest_3","region_id":"meokbi_forest","ground_name":"비가 처음 내린 자리","description":"먹비가 그치지 않는 숲의 가장 깊은 곳.","depth":3,"danger":10,"min_level":45,"unlock_progress":70},{"ground_id":"myeongbu_tower_1","region_id":"myeongbu_tower","ground_name":"무너진 아래층","description":"죽간이 쏟아져 내린 탑 아래층.","depth":1,"danger":10,"min_level":44,"unlock_progress":0},{"ground_id":"myeongbu_tower_2","region_id":"myeongbu_tower","ground_name":"회수 명부 층","description":"거둔 이름을 묶어 둔 서가가 늘어선 층.","depth":2,"danger":10,"min_level":45,"unlock_progress":30},{"ground_id":"myeongbu_tower_3","region_id":"myeongbu_tower","ground_name":"탑 꼭대기 누각","description":"마지막 먹귀들이 엉켜 있는 꼭대기.","depth":3,"danger":10,"min_level":45,"unlock_progress":70},{"ground_id":"nine_court_1","region_id":"nine_court","ground_name":"뜰 가장자리","description":"진의 바깥 금을 따라 도는 길.","depth":1,"danger":10,"min_level":45,"unlock_progress":0},{"ground_id":"nine_court_2","region_id":"nine_court","ground_name":"넷째 칸에서 여섯째 칸","description":"먹이 반쯤 마른 진의 안쪽.","depth":2,"danger":10,"min_level":45,"unlock_progress":30},{"ground_id":"nine_court_3","region_id":"nine_court","ground_name":"가운데 칸 앞","description":"매듭 안쪽으로 이어진 진의 한가운데.","depth":3,"danger":10,"min_level":45,"unlock_progress":70}]$J$::jsonb) as x(ground_id text, region_id text, ground_name text, description text, depth int, danger int, min_level int, unlock_progress int)
on conflict (ground_id) do update set ground_name = excluded.ground_name, description = excluded.description, min_level = excluded.min_level;
insert into public.world_fish_grounds(region_id, habitat, ground_name, description)
select x.region_id, x.habitat, x.ground_name, x.description from jsonb_to_recordset($J$[{"region_id":"mukchang_ferry","habitat":"river","ground_name":"먹물 여울","description":"먹빛 강물이 나루 앞에서 여울져 흐릅니다. 찌가 먹물에 반쯤 잠깁니다."},{"region_id":"mukchang_ferry","habitat":"sea","ground_name":"묵창 앞바다","description":"나루 끝 선창 너머로 검푸른 바다가 열립니다. 물결마다 지워진 글자 같은 무늬가 일렁입니다."},{"region_id":"blank_field","habitat":"marsh","ground_name":"번진 먹 늪","description":"먹이 번진 늪. 물풀 사이로 무언가 천천히 지나갑니다."},{"region_id":"meokbi_forest","habitat":"lake","ground_name":"먹비 고인 못","description":"먹비가 고여 생긴 못. 빗방울이 떨어질 때마다 남의 꿈이 비쳤다 사라집니다."},{"region_id":"myeongbu_tower","habitat":"canal","ground_name":"탑 밑 먹 수로","description":"탑 아래로 먹물 섞인 물이 흐르는 수로. 죽간 조각이 떠내려옵니다."},{"region_id":"nine_court","habitat":"deep","ground_name":"아홉째 칸 우물","description":"뜰 끝의 깊은 우물. 낚싯줄을 다 풀어도 바닥에 닿지 않습니다."}]$J$::jsonb) as x(region_id text, habitat text, ground_name text, description text)
on conflict (region_id, habitat) do update set ground_name = excluded.ground_name, description = excluded.description;
insert into public.world_region_sites(site_id, region_id, site_name, site_type, bonus_item, loot_table, rare_bonus, description, bonus_chance, loot_category, loot_categories, active)
