insert into public.world_status_catalog(status_key, status_name, polarity, description, duration_minutes, effects, icon)
select x.status_key, x.status_name, x.polarity, x.description, x.duration_minutes, x.effects, x.icon from jsonb_to_recordset($J$[{"status_key":"clear_name","status_name":"또렷한 이름","polarity":"positive","duration_minutes":120,"effects":{},"icon":"spark","description":"제 이름이 또렷이 새겨져 있습니다. 묵적록의 이름 흐림이 걸리지 않습니다."},{"status_key":"name_ward","status_name":"이름 지킴","polarity":"positive","duration_minutes":60,"effects":{},"icon":"shield","description":"이름 먹 부적이 이름을 지킵니다. 묵적록의 이름 흐림이 걸리지 않습니다."},{"status_key":"meokgwi_repel","status_name":"먹귀 쫓김","polarity":"positive","duration_minutes":60,"effects":{"encounter_pct":-20,"mental_loss_pct":-5},"icon":"flame","description":"먹귀 쫓는 향 냄새가 배어 요괴와 덜 마주칩니다."},{"status_key":"rain_shelter","status_name":"먹비 가림","polarity":"positive","duration_minutes":60,"effects":{"incoming_damage_pct":-8},"icon":"shield","description":"먹비 우산이 먹비와 함께 날아드는 것을 막아 줍니다."},{"status_key":"dark_eye","status_name":"어둠 눈","polarity":"positive","duration_minutes":60,"effects":{"clue_bonus_pct":6},"icon":"spark","description":"어둠 속에서도 작은 흔적이 눈에 들어옵니다."},{"status_key":"blank_fill","status_name":"빈칸 메움","polarity":"positive","duration_minutes":60,"effects":{"erosion_pct":-30},"icon":"leaf","description":"빈칸이 메워져 몸에 스미는 요기가 줄어듭니다."},{"status_key":"rain_clear","status_name":"먹비 걷힘","polarity":"positive","duration_minutes":120,"effects":{"fish_bite_pct":10,"gather_qty_pct":8},"icon":"leaf","description":"눈앞의 먹비가 걷힌 듯 물고기와 채집거리가 잘 보입니다."},{"status_key":"brush_mind","status_name":"붓끝 정신","polarity":"positive","duration_minutes":120,"effects":{"training_xp_pct":10},"icon":"spark","description":"붓끝처럼 정신이 모여 기술이 잘 늡니다."},{"status_key":"dragon_eye","status_name":"용안","polarity":"positive","duration_minutes":180,"effects":{"rare_loot_pct":5,"clue_bonus_pct":5},"icon":"spark","description":"눈먼 용의 눈이 대신 봐 주어 귀한 것과 단서가 잘 보입니다."},{"status_key":"gentle_tide","status_name":"순한 물길","polarity":"positive","duration_minutes":120,"effects":{"travel_time_pct":-10,"incoming_damage_pct":-5},"icon":"leaf","description":"물길이 순해져 길이 빠르고 몸이 덜 다칩니다."}]$J$::jsonb) as x(status_key text, status_name text, polarity text, description text, duration_minutes int, effects jsonb, icon text)
