  from jsonb_to_recordset($J$[{"k":"fr_mukjeok","kind":"frame","tier":"legend","name":"먹비 테","cond":"묵적록 다섯 곳에 모두 닿으면","rule":{"title":"mk_walker"},"sort":1500},{"k":"sl_muk","kind":"seal","tier":"legend","name":"낙관 「墨」","cond":"명어 여섯을 모두 낚으면","rule":{"title":"mk_named_all"},"sort":1501}]$J$::jsonb) as x(k text, kind text, tier text, name text, cond text, rule jsonb, sort int)
